package bundle

import "testing"

// specKey is a key of the form the spec pattern recognises.
const specKey = "SPEC" + "-138-A01"

func hasReference(refs []Reference, kind, value string) bool {
	for _, r := range refs {
		if r.Kind == kind && r.Value == value {
			return true
		}
	}
	return false
}

func TestExtractReferences(t *testing.T) {
	text := "Fixes ABC-521 and implements " + specKey + ". This cherry-picks #42 and is stacked on #10. Supersedes #7. Includes #3. Follow-up to #99.\n" +
		"Generated by Claude Code from an agent session.\n" +
		"See screenshot at https://example.com/shot.png and demo https://example.com/demo.mp4"
	refs := ExtractReferences(text, "body")

	if !hasReference(refs, ReferenceIssueKey, "ABC-521") {
		t.Errorf("expected ABC-521 issue key, got %+v", refs)
	}
	if !hasReference(refs, ReferenceSpec, specKey) {
		t.Errorf("expected %s, got %+v", specKey, refs)
	}
	if !hasReference(refs, ReferenceCherryPick, "#42") {
		t.Errorf("expected cherry-pick #42, got %+v", refs)
	}
	if !hasReference(refs, ReferenceStackedOn, "#10") {
		t.Errorf("expected stacked-on #10, got %+v", refs)
	}
	if !hasReference(refs, ReferenceSupersedes, "#7") {
		t.Errorf("expected supersedes #7, got %+v", refs)
	}
	if !hasReference(refs, ReferenceIncludes, "#3") {
		t.Errorf("expected includes #3, got %+v", refs)
	}
	if !hasReference(refs, ReferenceFollowUp, "#99") {
		t.Errorf("expected follow-up #99, got %+v", refs)
	}
	foundDisclosure := false
	for _, r := range refs {
		if r.Kind == ReferenceAuthorshipDisclosure {
			foundDisclosure = true
		}
	}
	if !foundDisclosure {
		t.Errorf("expected an authorship disclosure reference, got %+v", refs)
	}
	if !hasReference(refs, ReferenceImage, "https://example.com/shot.png") {
		t.Errorf("expected image reference, got %+v", refs)
	}
	if !hasReference(refs, ReferenceVideo, "https://example.com/demo.mp4") {
		t.Errorf("expected video reference, got %+v", refs)
	}
	for _, r := range refs {
		if r.Source != "body" {
			t.Errorf("expected every reference sourced from %q, got %q", "body", r.Source)
		}
	}
}

func TestExtractReferencesEmptyText(t *testing.T) {
	if refs := ExtractReferences("", "body"); refs != nil {
		t.Errorf("expected nil for empty text, got %+v", refs)
	}
}

func TestExtractReferencesRunsBeforeTrimming(t *testing.T) {
	// An issue key inside text that trimming later removes is still
	// extracted: references are collected before ApplyCaps and Fit. Here we
	// confirm extraction itself works on text
	// that a later trim pass would remove (e.g. an older prompt).
	trimmedAwayText := "This mentions ABC-49 but will be cut by the byte-limit trim pass."
	refs := ExtractReferences(trimmedAwayText, "prompt")
	if !hasReference(refs, ReferenceIssueKey, "ABC-49") {
		t.Fatalf("expected ABC-49 extracted even though its text would later be trimmed, got %+v", refs)
	}
}

// TestCollectReferencesUsesHeadRefNotBaseRef guards against extracting
// branch references from the base ref (almost always the default branch)
// instead of the pull request's own head ref, where a contributor actually
// puts ticket keys.
func TestCollectReferencesUsesHeadRefNotBaseRef(t *testing.T) {
	bundle := Bundle{PullRequest: PullRequest{
		BaseRef: "main",
		HeadRef: "feature/ABC-777-do-the-thing",
	}}
	refs := CollectReferences(bundle)
	found := false
	for _, r := range refs {
		if r.Kind == ReferenceIssueKey && r.Value == "ABC-777" {
			found = true
			if r.Source != "branch" {
				t.Errorf("expected source %q, got %q", "branch", r.Source)
			}
		}
	}
	if !found {
		t.Fatalf("expected ABC-777 extracted from HeadRef, got %+v", refs)
	}

	// The base ref must not be a reference source: a key that only appears
	// in a differently-named base branch (simulating the bug) must not leak
	// in via CollectReferences.
	bundleBaseOnly := Bundle{PullRequest: PullRequest{
		BaseRef: "release/ABC-999",
		HeadRef: "feature/no-ticket",
	}}
	refs = CollectReferences(bundleBaseOnly)
	for _, r := range refs {
		if r.Value == "ABC-999" {
			t.Fatalf("base ref must not be scanned for references, got %+v", refs)
		}
	}
}
